    private static readonly (Regex Rx, string En)[] Patterns =
    {
        (new(@"^Özel alan: (.+)$"), "Custom field: $1"),
        (new(@"^(.+) \(özel nitelikli\)$"), "$1 (special category)"),
        (new(@"^İşten ayrılıştan (\d+) ay sonra otomatik silinir$"), "Deleted automatically $1 months after leaving"),
        (new(@"^Değer AES-256-GCM şifreli; onaylı gizlilik etki değerlendirmesi var; İK görüntülemeleri kaydedilir; Görünürlük düzeyi: (\w+)( \(alan pasif\))?$"),
            "Value encrypted with AES-256-GCM; approved privacy impact assessment; HR views are logged; Visibility: $1$2"),
        (new(@"^Görünürlük düzeyi: (\w+)( \(alan pasif\))?$"), "Visibility: $1$2"),
    };

    /// <summary>Metnin İngilizcesi (katalog dışı/düzenlenmiş metin aynen döner).</summary>
    public static string T(string? tr)
    {
        if (string.IsNullOrEmpty(tr)) return tr ?? "";
        if (Map.TryGetValue(tr, out var en)) return en;
        foreach (var (rx, pattern) in Patterns)
            if (rx.IsMatch(tr)) return rx.Replace(tr, pattern).Replace(" (alan pasif)", " (field inactive)");
        return tr;
    }

    public static string[] T(IEnumerable<string> items) => items.Select(T).ToArray();

    public static ProcessingActivity Translate(ProcessingActivity a) => a with
    {
        Module = T(a.Module),
        Activity = T(a.Activity),
        Subjects = T(a.Subjects),
        DataCategories = T(a.DataCategories),
        Purpose = T(a.Purpose),
        LegalBasis = T(a.LegalBasis),
        Retention = T(a.Retention),
        Recipients = T(a.Recipients),
        Measures = T(a.Measures),
    };

